  "implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    for _ in range(max_rounds):
        original = text
        for p in passes:
            text = text.replace(p['old'], p['new'])
            applications.append(p['name'])
        if text == original:
            return {
                'applications': applications,
                'fixed_point': True,
                'text': text
            }
    return {
        'applications': applications,
        'fixed_point': False,
        'text': text
    }"
}
